import java.util.Optional;

public class Main {
    static Optional<String> find(String key) {
        if (key.equals("{k1}")) {
            return Optional.of("{v1}");
        }
        if (key.equals("{k2}")) {
            return Optional.of("{v2}");
        }
        return Optional.empty();
    }

    static Optional<String> report(String key) {
        return find(key).map(s -> s + " 有 " + s.length() + " 个字");
    }

    public static void main(String[] args) {
        System.out.println(report("{k1}").orElse("{k1} 不在柜子里"));
        System.out.println(report("{k3}").orElse("{k3} 不在柜子里"));
    }
}
